const weatherMoves={'Rain Dance':'Rain','Sunny Day':'Sun',Sandstorm:'Sand',Hail:'Snow',Snowscape:'Snow'};
const terrainMoves={'Electric Terrain':'Electric','Grassy Terrain':'Grass','Misty Terrain':'Fairy','Psychic Terrain':'Psychic'};
function moveRules(move) {
 const [target,category,changes,statChance,ailment,ailmentChance,healing] = moveData[move] ?? [10,2,[],0,0,0,0];
 const [type,power,,priority,status,drain,,configuredArea] = moveCatalog[move];
 const scope = (Object.hasOwn(weatherMoves,move) || Object.hasOwn(terrainMoves,move) || [3,4,5,7,13,15].includes(target)) ? 'ally' :
  configuredArea || [6,9,11,12,14].includes(target) ? 'area' : 'single';
 const melee = ['Tackle','Scratch','Bite','Quick Attack','Aqua Tail','Flame Wheel','Struggle'].includes(move)
  || (category===2 && !['Rock','Ground','Flying'].includes(type));
 const range = scope==='ally' ? 0 : melee ? 16 : category===1 ? 115 : 110+Math.min(70,power*0.65);
 const radius = scope==='area' ? Math.round(35+Math.min(62,power*0.55)) : 0;
 const statImpact = changes.reduce((sum,[,stages])=>sum+Math.abs(stages),0);
 const cooldown = status ? 3+healing*0.065+statImpact*0.8+(ailment ? 1.6 : 0)+(scope==='area' ? 0.6 : 0) :
  0.9+(power||55)*0.036+(scope==='area' ? 0.65 : 0)+drain*1.2-Math.max(0,priority)*0.25;
 return {cooldown:Math.round(cooldown*10)/10,target,category,changes,statChance,ailment,ailmentChance,healing,scope,range,radius};
}
