const speciesById=Object.fromEntries(Object.entries(dex).map(([name,[id]])=>[id,name]));
const wildRegions=['Kanto','Johto','Hoenn','Sinnoh','Unova','Kalos','Alola','Galar','Paldea'];
const wildDifficulties=['I','II','III','IV','V','VI','VII','VIII','IX','X'].map((label,index)=>({
 label,min:index===9?90:index*10+1,max:index===8?89:(index+1)*10
}));
for(const [index,tier] of wildDifficulties.entries()) {
 const option=element('option',tier.label+' · Lv. '+tier.min+'–'+tier.max);
 option.value=String(index);
 byId('wild-difficulty').append(option);
 byId('trainer-difficulty').append(option.cloneNode(true));
}
function rollWildLevel(tier) {
 return tier.min+Math.floor(onlineRandom()*(tier.max-tier.min+1));
}
const ballTypes=[
 {name:'Poké Ball',multiplier:()=>1},
 {name:'Great Ball',multiplier:()=>1.5},
 {name:'Ultra Ball',multiplier:()=>2},
 {name:'Net Ball',multiplier:({name})=>dex[name].slice(1,3).some(type=>type==='Bug'||type==='Water')?3.5:1},
 {name:'Nest Ball',multiplier:({level})=>Math.max(1,(41-level)/10)},
 {name:'Timer Ball',multiplier:({duration})=>Math.min(4,1+duration/20)},
 {name:'Master Ball',multiplier:()=>Infinity}
];
