const guardMoves=new Set(['Protect','Detect','Endure','Wide Guard','Quick Guard','Reflect','Light Screen']);
function skillItem(move) {
 const kind=machineKinds[move] ?? 'TM';
 const name=(Object.hasOwn(machineKinds,move)?kind:'Arena TM')+' · '+move;
 const [,power,accuracy,priority,status,drain,recoil]=moveCatalog[move];
 const rules=moveRules(move);
 const reliability=accuracy/100;
 const effectivePower=(power||55)*reliability*(1-recoil*0.35);
 const statImpact=rules.changes.reduce((sum,[,stages])=>sum+Math.abs(stages),0);
 const hasAilment=[1,2,3,4,5].includes(rules.ailment);
 const ailmentValue=rules.ailment===2 || rules.ailment===3 ? 440 : 245;
 let value=120;
 if(status) {
  value+=(rules.healing || (move==='Aqua Ring'?20:0))*11;
  value+=statImpact*110*reliability;
  if(hasAilment) value+=ailmentValue*reliability;
  if(guardMoves.has(move)) value+=130;
 } else {
  value+=Math.max(0,effectivePower-40)*7+Math.max(0,effectivePower-80)*9;
  value+=drain*180+Math.max(0,priority)*35;
  value+=statImpact*95*rules.statChance/100;
  if(hasAilment) value+=ailmentValue*rules.ailmentChance/100;
 }
 if(rules.scope==='area' && value>120) value+=140;
 if([13,15].includes(rules.target) && value>120) value+=135;
 return {kind,name,price:Math.min(1500,Math.ceil(value/5)*5)};
}
