 if(remaining) {
  wildProgress.owned[name]={level:remaining.level,xp:remaining.xp};
  profiles[sourceId]=remaining.profile;
  wildProgress.ai[name]=normalizeBattleAI(remaining.ai);
  if(remaining.moves?.length)loadouts[name]=legalLoadout(name,remaining.moves);
  if(remaining.held && (!evolutionStones.includes(remaining.held) || stoneTarget(name,remaining.held)) && freeHeldCopies(remaining.held,name)>0)wildProgress.held[name]=remaining.held;
 }
