function canCatchResult(result) {
 return result && !result.resolved;
}
const ballColors=['#ed4757','#408afa','#29253d','#28a987','#82ad45','#f08255','#9456cf'];
const captureDuration=4200;
function tryCatch(index) {
 const result=wildResult;
 if(!canCatchResult(result) || !wildProgress.balls[index] || !ballTypes[index]) return;
 wildProgress.balls[index]--;
 result.resolved=true;
 captureMenu=false;
 difficultyMenu=false;
 cancelWildRepeat();
 const caught=onlineRandom()<catchChance(ballTypes[index],result);
 const reduced=typeof matchMedia==='function' && matchMedia('(prefers-reduced-motion: reduce)').matches;
 const duration=reduced?250:captureDuration;
 result.capture={index,caught,pending:true,duration};
 if(caught) {
  addCaughtPokemon(result.name,result.level);
 }
 saveWildProgress();
 renderWildResult();
 setTimeout(()=>{
  if(wildResult!==result || phase!=='wild-result') return;
  result.capture.pending=false;
  result.message+=caught ? ' '+result.name+' was caught!' :
   ' '+result.name+' broke free, destroyed the '+ballTypes[index].name+', and escaped.';
  runWildResultOptions();
 },duration);
}
function captureArtwork(name,capture) {
 const art=element('div',null,'wild-victory-art');
 if(!capture) {
  art.append(pokemonPortrait(name));
  return art;
 }
 art.className+=' '+(capture.pending?'catch-playing':'catch-settled')+' '+(capture.caught?'catch-caught':'catch-escape');
 art.style.setProperty('--ball-top',ballColors[capture.index]);
 art.style.setProperty('--catch-time',capture.duration+'ms');
 const creature=element('div',null,'catch-creature');
 creature.append(pokemonPortrait(name));
 art.append(creature,element('div',null,'catch-orb'),element('div',null,'catch-pulse'));
 if(!capture.caught) {
  const shards=element('div',null,'catch-shards');
  for(let index=0;index<6;index++) {
   const piece=element('i');
   const angle=index*Math.PI/3;
   piece.style.setProperty('--shard-x',Math.round(Math.cos(angle)*52)+'px');
   piece.style.setProperty('--shard-y',Math.round(27+Math.sin(angle)*42)+'px');
   shards.append(piece);
  }
  art.append(shards);
 }
 return art;
}
function repeatWildBattle() {
 const result=wildResult;
 if(!result || result.capture?.pending) return;
 cancelWildRepeat();
 const tier=wildDifficulties.find(tier=>tier.label===result.tier) ?? currentWildTier();
 encounterIn(result.region,tier);
}
function runWildResultOptions() {
 cancelWildRepeat();
 if(phase!=='wild-result' || !wildResult || wildResult.capture?.pending) return;
 if(wildProgress.autoCapture && canCatchResult(wildResult) && !difficultyMenu) {
  const first=wildProgress.balls.findIndex(count=>count>0);
  if(first>=0) {tryCatch(first);return;}
 }
 renderWildResult();
 if(wildProgress.autoRepeat && !difficultyMenu && !captureMenu) {
  repeatTimer=setTimeout(()=>{
   repeatTimer=null;
   if(phase==='wild-result' && wildProgress.autoRepeat) repeatWildBattle();
  },2200);
 }
}
function renderWildResult() {
 if(phase!=='wild-result' || !wildResult) return;
 const panel=byId('wild-result');
 const {name,level,message,region,tier,resolved,capture:animation}=wildResult;
 const label=element('p',animation?.pending ? 'Attempting capture with '+ballTypes[animation.index].name+'…' : message);
 label.setAttribute('role','status');
 panel.replaceChildren(element('h2','Wild Pokémon defeated'),captureArtwork(name,animation),
  pokemonNameplate(name,' · Lv. '+level+(isLegendaryEncounter(name)?' · Legendary or Mythical':''),'h3'),
  element('p',region+' · Difficulty '+tier),label);
 if(animation?.pending) return;
 const experience=element('details');
 const xpList=element('ul');
 for(const award of wildResult.awards) xpList.append(element('li',award.name+' · +'+award.xp+' XP ('+award.share+'%)'));
 experience.append(element('summary','Team XP'),xpList);
 panel.append(experience);
 const toggles=element('div',null,'wild-toggles');
 renderAutoOptions(toggles,runWildResultOptions);
 panel.append(toggles);
 const actions=element('div',null,'wild-actions');
 const capture=element('button','Capture');
 capture.disabled=!canCatchResult(wildResult) || !wildProgress.balls.some(Boolean);
 capture.onclick=()=>{captureMenu=!captureMenu;difficultyMenu=false;runWildResultOptions();};
 const regions=element('button','Select Region');
 regions.onclick=openWildRegions;
 const difficulty=element('button','Select Difficulty');
 difficulty.onclick=()=>{difficultyMenu=!difficultyMenu;captureMenu=false;runWildResultOptions();};
 const repeat=element('button','Next Encounter');
 repeat.onclick=repeatWildBattle;
 const home=element('button','Main menu');
 home.onclick=openMenu;
 actions.append(capture,regions,difficulty,repeat,home);
 panel.append(actions);
 if(!resolved && ownedPokemon(name)) panel.append(element('p','Already in your collection.'));
 if(captureMenu && !capture.disabled) {
  const choices=element('div',null,'wild-actions');
  for(const [index,ball] of ballTypes.entries()) {
   if(!wildProgress.balls[index]) continue;
   const choice=element('button',ball.name+' ×'+wildProgress.balls[index]);
   choice.append(element('small',Math.round(catchChance(ball,wildResult)*100)+'% catch chance'));
   choice.onclick=()=>tryCatch(index);
   choices.append(choice);
  }
  panel.append(choices);
 }
 if(difficultyMenu) {
  const label=element('label','Repeat difficulty','wild-difficulty');
  const select=element('select');
  for(const [index,option] of wildDifficulties.entries()) {
   const node=element('option',option.label+' · Lv. '+option.min+'–'+option.max);
   node.value=String(index);
   select.append(node);
  }
  select.value=String(wildDifficulties.findIndex(option=>option.label===tier));
  const apply=element('button','Apply');
  apply.onclick=()=>{
   byId('wild-difficulty').value=select.value;
   wildResult.tier=currentWildTier().label;
   difficultyMenu=false;
   runWildResultOptions();
  };
  label.append(select,apply);
  panel.append(label);
 }
 if(wildProgress.autoRepeat && !difficultyMenu && !captureMenu) panel.append(element('p','Auto repeat will start another encounter shortly.','wild-victory-note'));
}
