 const aces=signature.split(',').filter(isAvailablePokemon);
 const candidates=dexNames.filter(name=>{
  const [id,primary,secondary]=dex[name];
  return id<=generationLastId[generation-1] && !aces.includes(name) &&
   (specialties.includes(primary)||specialties.includes(secondary));
 });
 const pool=[...candidates,...aces];
 const roster=[...aces,...Array.from({length:6-aces.length},(_,i)=>pool[i%pool.length])];
