const recordedBattleMusic={"Hoenn:trainer":"./assets/battle-01.mp3","Johto:trainer":"./assets/battle-02.mp3","Johto:gym":"./assets/battle-03.mp3","Galar:wild":"./assets/battle-04.mp3","Johto:wild":"./assets/battle-05.mp3","Alola:wild":"./assets/battle-06.mp3","Hoenn:wild":"./assets/battle-07.mp3","Alola:trainer":"./assets/battle-08.mp3","Galar:gym":"./assets/battle-09.mp3","Alola:gym":"./assets/battle-10.mp3","Hoenn:gym":"./assets/battle-11.mp3","Galar:trainer":"./assets/battle-12.mp3","Kalos:trainer":"./assets/battle-13.mp3","Kalos:gym":"./assets/battle-14.mp3","Paldea:trainer":"./assets/battle-15.mp3","Sinnoh:wild":"./assets/battle-16.mp3","Kanto:wild":"./assets/battle-17.mp3","Kanto:trainer":"./assets/battle-18.mp3","Sinnoh:gym":"./assets/battle-19.mp3","Kalos:wild":"./assets/battle-20.mp3","Kanto:gym":"./assets/battle-21.mp3","Paldea:gym":"./assets/battle-22.mp3","Sinnoh:trainer":"./assets/battle-23.mp3","Paldea:wild":"./assets/battle-24.mp3","Unova:wild":"./assets/battle-25.mp3","Unova:gym":"./assets/battle-26.mp3","Unova:trainer":"./assets/battle-27.mp3"};
let musicContext,musicTrack;
function stopBattleMusic() {
 if(!musicTrack) return;
 if(musicTrack.audio) musicTrack.audio.pause();
 else {
  clearInterval(musicTrack.timer);
  musicTrack.output.disconnect();
 }
 musicTrack=null;
}
function musicNote(output,voice,midi,time,duration,volume) {
 const oscillator=musicContext.createOscillator();
 const envelope=musicContext.createGain();
 oscillator.type=voice;
 oscillator.frequency.value=440*2**((midi-69)/12);
 envelope.gain.setValueAtTime(0.0001,time);
 envelope.gain.exponentialRampToValueAtTime(volume,time+0.012);
 envelope.gain.exponentialRampToValueAtTime(0.0001,time+duration);
 oscillator.connect(envelope);
 envelope.connect(output);
 oscillator.onended=()=>{oscillator.disconnect();envelope.disconnect();};
 oscillator.start(time);
 oscillator.stop(time+duration+0.01);
}
const victoryRecordings={"wild":"./assets/battle-28.mp3","trainer":"./assets/battle-29.mp3","gym":"./assets/battle-30.mp3"};
function playVictoryMusic(kind) {
 stopBattleMusic();
 if(!battleMusicEnabled || !window.Audio) return;
 const audio=new window.Audio(victoryRecordings[kind]);
 audio.volume=0.35;
 musicTrack={audio};
 audio.play().catch(()=>{});
}
function startBattleMusic() {
 const Audio=window.AudioContext ?? window.webkitAudioContext;
 if(!battleMusicEnabled || musicTrack) return;
 const region=selectedWild?.region ?? selectedTrainer?.region ?? selectedGym?.region ?? rogueRun?.region ?? 'Kanto';
 const kind=selectedWild?'wild':selectedGym?'gym':'trainer';
 const recording=recordedBattleMusic[region+':'+kind];
 if(recording) {
  const audio=new window.Audio(recording);
  audio.loop=true;
  audio.volume=0.35;
  musicTrack={audio};
  audio.play().catch(()=>{});
  return;
 }
 if(!Audio) return;
 const theme=regionBattleThemes[region] ?? regionBattleThemes.Kanto;
 try {
  musicContext ??=new Audio();
  musicContext.resume().catch(()=>{});
  const output=musicContext.createGain();
  output.gain.value=0.22;
  output.connect(musicContext.destination);
  const stepTime=30/theme.bpm;
  let next=musicContext.currentTime+0.04;
  let step=0;
  const pitch=degree=>theme.key+theme.scale[degree%7]+12*Math.floor(degree/7);
  const schedule=()=>{
   if(musicContext.state!=='running') return;
   const now=musicContext.currentTime;
   if(next<now-0.25) next=now+0.04;
   while(next<now+0.16) {
    const beat=step%8;
    const bar=Math.floor(step/8);
    const root=theme.roots[bar%theme.roots.length];
    const melody=theme.motif[step%theme.motif.length];
    if(melody!==null) musicNote(output,theme.voice,pitch(root+melody),next,stepTime*0.9,0.20);
    if(beat%2===0) musicNote(output,'triangle',pitch(root+(beat===6?4:0))-12,next,stepTime*1.55,0.23);
    if(beat===0 || beat===4) {
     for(const interval of [0,2,4]) musicNote(output,'triangle',pitch(root+interval),next,stepTime*2.8,0.047);
    }
    if(beat===0 || beat===3 || beat===4) musicNote(output,'sine',36,next,0.085,0.16);
    if(beat===2 || beat===6) musicNote(output,'sawtooth',69,next,0.055,0.047);
    next+=stepTime;
    step++;
   }
  };
  musicTrack={output,timer:setInterval(schedule,50)};
  schedule();
 } catch {stopBattleMusic();}
}
