const skillSoundProfiles={
 Fire:[110,48,'sawtooth'], Water:[630,270,'sine'], Electric:[720,135,'square'],
 Ice:[900,430,'triangle'], Grass:[490,205,'triangle'], Psychic:[320,760,'sine'],
 Ghost:[380,145,'sine'], Dark:[240,68,'triangle'], Dragon:[165,65,'sawtooth'],
 Fighting:[185,55,'triangle'], Rock:[125,42,'triangle'], Ground:[88,33,'sine'],
 Flying:[550,160,'triangle'], Steel:[840,340,'triangle'], Fairy:[520,980,'sine'],
 Poison:[285,120,'square'], Bug:[580,240,'square']
};
function unlockSkillSound() {
 if(!skillSoundEnabled) return;
 const Audio=window.AudioContext ?? window.webkitAudioContext;
 if(!Audio) return;
 try {
  musicContext ??=new Audio();
  if(musicContext.state==='suspended') musicContext.resume().catch(()=>{});
 } catch {}
}
const moveSoundSignatures=new Map(Object.keys(moveCatalog).map((move,index,all)=>{
 const [type,power]=moveCatalog[move];
 const [high,low,voice]=skillSoundProfiles[type] ?? [340,110,'triangle'];
 const seed=[...move].reduce((value,character)=>(Math.imul(value,31)+character.charCodeAt(0))>>>0,7);
 return [move,{high:high*(0.72+0.56*index/all.length),low:low*(0.7+(seed%47)/70),
  voice,tail:['sine','triangle','square'][seed%3],accent:1.1+(seed%19)/15,
  length:0.9+Math.min(power || 0,160)/400+(seed%11)/50}];
}));
function playSkillSound(move,event,shape) {onlineSounds.push({move,event,shape,clock});}
function browserSkillSound(move,event,shape) {
 if(!skillSoundEnabled || musicContext?.state!=='running') return;
 const signature=moveSoundSignatures.get(move);
 if(!signature) return;
 const {high,low,voice,tail,accent,length}=signature;
 const duration=(event==='warning'?0.075:event==='impact'?0.095:shape==='beam'?0.28:0.17)*length;
 const start=event==='impact'?low*0.9:event==='warning'?high*0.64:high;
 const end=event==='warning'?high:event==='impact'?Math.max(32,low*0.52):low;
 const volume=event==='warning'?0.018:event==='impact'?0.065:0.052;
 const time=musicContext.currentTime;
 skillSoundVoice(event==='impact'?'triangle':voice,start,end,duration,volume,time);
 if(event!=='warning') {
  const overtone=event==='impact'?high*0.7:start*accent;
  skillSoundVoice(tail,overtone,Math.max(24,end*accent),duration*0.64,volume*0.36,time+0.018);
 }
}
function skillSoundVoice(voice,start,end,duration,volume,time) {
 const oscillator=musicContext.createOscillator();
 const gain=musicContext.createGain();
 oscillator.type=voice;
 oscillator.frequency.setValueAtTime(start,time);
 oscillator.frequency.exponentialRampToValueAtTime(end,time+duration);
 gain.gain.setValueAtTime(0.0001,time);
 gain.gain.exponentialRampToValueAtTime(volume,time+0.009);
 gain.gain.exponentialRampToValueAtTime(0.0001,time+duration);
 oscillator.connect(gain);
 gain.connect(musicContext.destination);
 oscillator.onended=()=>{oscillator.disconnect();gain.disconnect();};
 oscillator.start(time);
 oscillator.stop(time+duration+0.01);
}
